import sys
sys.dont_write_bytecode=True
import additional_pfp_domain_remaining_audit as a
rows=[
('bqnf_validator.py',326,'CDC evaluator tracks declared attributes only, ignores relation matching, uses first predicate/group and defaults unsupported aggregate kinds to SUM. UPDATE between groups yields one new-group delta rather than removal/insertion in both groups; AVG ignores predicates. COUNT substring suffices to claim auxiliary support without validating complete SUM/COUNT state. Numeric conversions use float, counts int-truncate, nonpositive resulting count maps mean to zero, yet repairs default certified true. Missing columns and MAX/MIN generally refuse; foreign operations result import not executed. This is a restricted example evaluator, not an exact general coboundary checker.'),
('bqnf_fsign.py',571,'Actual finite rational weight cancellation checks closed involution, no fixed points, opposite signed weights of equal magnitude and coverage of all negative weights. Stoquastic route checks explicit real symmetric matrix offdiagonals nonpositive, giving positivity conditional on the standard real-beta finite Hamiltonian interpretation. Determinant route checks supplied U, spin matrices and chemical potentials for a conditional registered theorem; no Hamiltonian construction, beta validation, physical model/source binding or determinant computation. Odd-cycle gauge witness establishes only alternating site-sign obstruction. C3 enumerates 64 states and 96 positive/negative three-hop paths and verifies rational exponential inequalities; its all-long-path bounds and link to integrated physical weights are hardcoded assumptions, not derived here. Floats explicitly raise contamination refusal. LIFT is a hold, not a proof.'),
('quantum_forms.py',469,'BSS solves signed-edge XOR constraints by BFS and returns an exact diagonal sign transformation or inconsistent-cycle witness. Odd means odd sign-parity, not necessarily odd edge count. MIC verifies finite declared pairs, but duplicate path IDs overwrite and weight magnitudes need not be nonnegative; sign +1 survivor can have negative weight. Signs int-coerce, including fractional values. Exact arithmetic identity is checked only after normalization. Bucket sketch is a float heuristic with uniform-within-bucket interpolation; deletion knows buckets rather than membership and width is unvalidated. Repair compares to supplied full true_values by linear order statistic, so is a bounded oracle comparison, not an a priori sketch error theorem.'),
('reconciliation.py',399,'Freshness compares declared scope and lag/SLA, with no timestamp authentication; bool/nonfinite numeric values are not explicitly rejected. Observer relation is a preorder on fields, and chain verifier only inspects outputs without checking order premises. Loss-ledger digest hashes entries only; an erased_attributes-only ledger with no entries/sealed flag is accepted. Reconciliation accepts target_verifier outcome verified without authenticated record, emits authorized true even for empty inputs and claims bidirectional commute although only an aggregate projection is compared. Duplicate target balances overwrite, colon-concatenated account/currency keys can alias, numeric types are not exact-int enforced. Compensation checking is finite equality of declared totals, not general homology.'),
('topology.py',372,'Integer Smith reduction uses minimum pivot, Euclidean row/column elimination and divisibility repair, without retaining unimodular transforms or validating rectangular integer inputs. Simplex orientation and duplicate checks plus explicit d1d2/d2d3 products are useful finite checks. Missing face edges/tetrahedron faces are defects, but an edge outside declared vertex set silently gets zero boundary and may be accepted. Betti ranks use finite chain formulas; Euler check cancels algebraically from those same ranks and is not independent evidence. Torsion combines invariant factors without degree labels; for valid free chain complexes this identifies torsion factors collectively, not a basis or cycle witness. No native computation.'),
('tower_forms.py',245,'TBNF delegates to pending tower parser after alphabet check. DBCNF computes least cyclic rotation; periodic minima need not be Lyndon words, and arbitrary Sequence slicing/concatenation may fail. ZFNF defaults missing feasibility to true, never binds claimed objective scalars to solution dot products and omits matrix from float scan: equal supplied scalars can certify optimality without a problem. Checks use primal x>=0/Ax=b and dual A-transpose y>=c when inputs exist, with dimensions trusted. DHNF checks reconstruction and pairwise dot orthogonality but never checks exact/coexact images or harmonic kernels; names on supplied vectors are trusted, so arbitrary c assigned wholly to d0_p receives exact decomposition.')]
for p,l,s in rows:a.record('pfp/domain/normal_forms/'+p,1,l,s)
a.record('pfp/domain/normal_forms/relational.py',1,220,'Read initial dependency/kernel layer: monotone finite attribute closure, exponential candidate key search excluding empty key, supplied nonempty determinant/dependent FD restriction. Schema lacks dependency-heading validation. 1NF only tests nonempty heading and assumes atomic domains. 2NF enumerates proper key subsets, 3NF/BCNF test supplied FD basis. Join dependencies require nonempty heading and union coverage, not unique/proper components. Remaining relational body pending.')
a.report()
